<?php
namespace App\Http\Controllers\Api\Staff;
use App\Http\Controllers\Controller;use App\Models\Report;use App\Models\ReportStatusHistory;use App\Notifications\ReportActivityNotification;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class StaffActionController extends Controller {public function update(Request $r,Report $report){abort_unless((int)$report->assigned_staff_id===(int)$r->user()->id,403);abort_unless($report->validation_status==='validated',422,'The report must be validated before field action.');$d=$r->validate(['status'=>'required|in:in_progress,resolved','notes'=>'required|string|min:5|max:5000','proof_photo'=>'required_if:status,resolved|nullable|image|max:5120']);abort_if($report->status==='resolved',422,'A resolved report can no longer be changed.');$path=$r->file('proof_photo')?->store("reports/{$report->id}/resolution",'public');DB::transaction(function()use($report,$r,$d,$path){ReportStatusHistory::create(['report_id'=>$report->id,'changed_by'=>$r->user()->id,'from_status'=>$report->status,'to_status'=>$d['status'],'notes'=>$d['notes'],'created_at'=>now()]);$report->update(['status'=>$d['status'],'resolution_notes'=>$d['status']==='resolved'?$d['notes']:null,'resolution_photo_path'=>$path?:$report->resolution_photo_path,'resolved_at'=>$d['status']==='resolved'?now():null]);$report->resident->notify(new ReportActivityNotification($report,'Report status updated',"{$report->reference_number} is now ".str_replace('_',' ',$d['status']).'.'));});return response()->json(['success'=>true,'message'=>'Field update saved.','data'=>$report->fresh()->load(['category','purok','photos','statusHistories'])]);}}
